const j = $('When Called').first().json || {};
const cur = $input.first().json || {};
const person = { etag: cur.etag };
const fields = [];
const name = String(j.name || '').trim();
if (name) { const parts = name.split(/\s+/); const given = parts.shift(); const nm = { givenName: given }; const family = parts.join(' '); if (family) nm.familyName = family; person.names = [nm]; fields.push('names'); }
const email = String(j.email || '').trim();
if (email) { person.emailAddresses = [{ value: email }]; fields.push('emailAddresses'); }
const phone = String(j.phone || '').trim();
if (phone) { person.phoneNumbers = [{ value: phone }]; fields.push('phoneNumbers'); }
const org = String(j.organization || '').trim();
const title = String(j.title || '').trim();
if (org || title) { const o = {}; if (org) o.name = org; if (title) o.title = title; person.organizations = [o]; fields.push('organizations'); }
const website = String(j.website || '').trim();
if (website) { person.urls = [{ value: website }]; fields.push('urls'); }
const rn = String(j.resourceName || '').trim();
const url = 'https://people.googleapis.com/v1/' + rn + ':updateContact?updatePersonFields=' + encodeURIComponent(fields.join(','));
return [{ json: { url, body: person, fieldsCount: fields.length } }];

const p = $input.first().json || {};
const name = ((p.names || [])[0] || {}).displayName || null;
const email = ((p.emailAddresses || [])[0] || {}).value || null;
const phone = ((p.phoneNumbers || [])[0] || {}).value || null;
const err = p.error ? (p.error.message || JSON.stringify(p.error)) : null;
return [{ json: { ok: !!p.resourceName && !err, resourceName: p.resourceName || null, name, email, phone, error: err } }];
